// Take the first row that has not been posted yet. No row → stop quietly.
const row = $input.all().map(i => i.json).find(r => !String(r.Status || '').trim());
if (!row) return [];
const destinations = [1, 2, 3, 4]
  .map(n => String(row[`Destination ${n}`] || '').trim())
  .filter(Boolean);
if (destinations.length !== 4) throw new Error(`Row ${row.row_number}: need 4 destinations, found ${destinations.length}`);
return [{ json: { row_number: row.row_number, topic: row.Topic || 'Hidden wonders', destinations } }];

// Turn Claude's JSON into 4 scene items (one per destination).
let res = $input.first().json;

// 1) Unwrap KIE envelope / string bodies
if (typeof res === 'string') res = JSON.parse(res);
if (typeof res.data === 'string') { try { res = JSON.parse(res.data); } catch (e) {} }
if (res.code && res.code !== 200) throw new Error(`KIE Claude error ${res.code}: ${res.msg}`);
const body = res.data && (res.data.content || res.data.choices) ? res.data : res;

// 2) Get the text (Anthropic format, or OpenAI-style fallback)
let text = '';
if (Array.isArray(body.content)) {
  text = body.content.filter(b => b.type === 'text').map(b => b.text).join('');
} else if (typeof body.content === 'string') {
  text = body.content;
} else if (body.choices?.[0]?.message?.content) {
  text = body.choices[0].message.content;
}
text = text.trim();
if (!text) throw new Error('Empty reply from Claude. Raw response: ' + JSON.stringify(res).slice(0, 500));
if (body.stop_reason === 'max_tokens') throw new Error('Claude reply was cut off (max_tokens). Raise max_tokens in Build Claude Request.');

// 3) Extract the JSON object even if there is text/fences around it
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start === -1 || end === -1) throw new Error('No JSON found in reply: ' + text.slice(0, 300));
let out;
try { out = JSON.parse(text.slice(start, end + 1)); }
catch (e) { throw new Error('Claude did not return valid JSON: ' + text.slice(0, 300)); }

if (!Array.isArray(out.scenes) || out.scenes.length !== 4) throw new Error('Expected exactly 4 scenes, got ' + (out.scenes?.length ?? 0));

const meta = $('Build Claude Request').first().json;
const hashtags = (out.hashtags || []).join(' ');
const caption = `${out.caption || ''}\n\n${hashtags}`.trim();

return out.scenes.map((s, i) => {
  const destination = s.destination || meta.destinations[i];
  let queries = (Array.isArray(s.search_queries) ? s.search_queries : [s.search_queries])
    .map(q => String(q || '').trim()).filter(Boolean);
  if (!queries.length) queries = [destination];
  while (queries.length < 3) queries.push(queries[queries.length - 1]);
  return { json: {
    scene: i + 1,
    row_number: meta.row_number,
    topic: meta.topic,
    title: (out.title || meta.topic).slice(0, 100),
    hook: out.hook || '',
    caption,
    music_mood: String(out.music_mood || 'calm').toLowerCase(),
    music_prompt: out.music_prompt || '',
    destination,
    role: s.role,
    label: s.label || destination,
    overlay: s.overlay || '',
    sound_prompt: s.sound_prompt || '',
    search_queries: queries.slice(0, 3)
  }};
});

// Pick the best free stock clip for every scene (Pexels first, Pixabay as fallback).
const CLIP_SECONDS = 7; // keep in sync with "Build Render Script"
const scenes = $('Parse Prompts').all().map(i => i.json);
const res = name => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };
const pexA = res('Search Pexels');
const pexB = res('Search Pexels (alt)');
const pix = res('Search Pixabay');

// tier 1 = no quality loss after cropping to 1080x1920, tier 2 = usable (slight upscale)
const tierOf = (w, h) => {
  const cropW = h > w ? w : Math.min(w, h * 9 / 16);
  const cropH = h > w ? Math.min(h, w * 16 / 9) : h;
  if (cropW >= 1080 && cropH >= 1900) return 1;
  if (h >= 1080) return 2;
  return 0;
};

const fromPexels = (r, rank) => (r?.videos || []).flatMap((v, idx) => {
  if ((v.duration || 0) < CLIP_SECONDS + 0.5) return [];
  const files = (v.video_files || [])
    .filter(f => f.link && String(f.file_type || '').includes('mp4') && f.width && f.height)
    .map(f => ({ ...f, tier: tierOf(f.width, f.height) }))
    .filter(f => f.tier > 0)
    // best tier first, then the smallest file that is still good (fast download)
    .sort((a, b) => a.tier - b.tier || a.width * a.height - b.width * b.height);
  const f = files[0];
  if (!f) return [];
  return [{ id: `pexels-${v.id}`, url: f.link, width: f.width, height: f.height, duration: v.duration,
    tier: f.tier, rank, idx, source: 'Pexels', credit: v.user?.name || 'Pexels', page: v.url }];
});

const fromPixabay = (r, rank) => (r?.hits || []).flatMap((h, idx) => {
  if ((h.duration || 0) < CLIP_SECONDS + 0.5) return [];
  const opts = ['large', 'medium'].map(k => h.videos?.[k]).filter(v => v && v.url && v.width && v.height)
    .map(v => ({ ...v, tier: tierOf(v.width, v.height) })).filter(v => v.tier > 0)
    .sort((a, b) => a.tier - b.tier || a.width * a.height - b.width * b.height);
  const f = opts[0];
  if (!f) return [];
  return [{ id: `pixabay-${h.id}`, url: f.url, width: f.width, height: f.height, duration: h.duration,
    tier: f.tier, rank, idx, source: 'Pixabay', credit: h.user || 'Pixabay', page: h.pageURL }];
});

const used = new Set();
const clips = scenes.map((s, i) => {
  const candidates = [
    ...fromPexels(pexA[i], 0),
    ...fromPexels(pexB[i], 1),
    ...fromPixabay(pix[i], 2)
  ].filter(c => !used.has(c.id))
   .sort((a, b) => a.tier - b.tier || a.rank - b.rank || a.idx - b.idx);
  const c = candidates[0];
  if (!c) throw new Error(`No usable stock clip for scene ${i + 1} (${s.destination}). Queries: ${s.search_queries.join(' | ')}. Add more generic queries or check your Pexels/Pixabay keys.`);
  used.add(c.id);
  // skip the first second (often a shaky start) when the clip is long enough
  const start = c.duration >= CLIP_SECONDS + 2 ? 1 : 0;
  return { scene: i + 1, destination: s.destination, label: s.label, overlay: s.overlay, sound_prompt: s.sound_prompt, role: s.role, start, ...c };
});

const m = scenes[0];
return [{ json: {
  row_number: m.row_number, topic: m.topic, title: m.title, hook: m.hook, caption: m.caption,
  music_mood: m.music_mood, music_prompt: m.music_prompt, clips,
  credits: clips.map(c => `${c.source}: ${c.credit}`).join(', ')
}}];

// Plans the sound for this video: one generated ambience per scene + one generated music cue.
// Each item is sent to the free local "audiogen" service (Stable Audio Open).
// ================== EDIT HERE ==================
const WORK_ROOT = '/home/node/.n8n-files/shorts';   // shared with the audiogen container
const CLIP_SECONDS = 7;        // keep in sync with "Build Render Script"
const GENERATE_MUSIC = true;   // false = use tracks from the music folder instead
const MUSIC_SECONDS = 11;      // stable-audio-open-small max ≈ 11s (looped smoothly). With stable-audio-open-1.0 use 30.
// ===============================================
const d = $input.first().json;
const job = `row${d.row_number}_${Date.now()}`;
const job_dir = `${WORK_ROOT}/${job}`;
const base = { job, job_dir, music_seconds: MUSIC_SECONDS, generate_music: GENERATE_MUSIC };
const withTail = (p, tail) => (String(p || '').trim().replace(/[.\s]+$/, '') + ', ' + tail).replace(/^, /, '');

const items = d.clips.map((c, i) => ({ json: { ...base,
  kind: 'ambience', index: i,
  prompt: withTail(c.sound_prompt || `natural ambient sound of ${c.destination}`, 'natural field recording, high quality, stereo, no music'),
  negative_prompt: 'music, melody, speech, voice, vocals, low quality, distorted, clipping',
  seconds: CLIP_SECONDS,
  out: `${job_dir}/amb${i}.wav`
}}));

if (GENERATE_MUSIC) items.push({ json: { ...base,
  kind: 'music', index: items.length,
  prompt: withTail(d.music_prompt || 'cinematic ambient piano with soft strings, slow, emotional, warm', 'instrumental, high quality, no vocals'),
  negative_prompt: 'vocals, singing, speech, harsh drums, low quality, distorted',
  seconds: MUSIC_SECONDS,
  out: `${job_dir}/music_gen.wav`
}});
return items;

// ================== EDIT HERE ==================
const MUSIC_DIR = '/home/node/.n8n-files/music';    // fallback tracks if music generation is off/failed (subfolders: calm, uplifting, epic, emotional)
const FONT = '/usr/share/fonts/custom/Poppins-SemiBold.ttf';
const FONT_FALLBACK = '/usr/share/fonts/dejavu/DejaVuSans-Bold.ttf';
const CLIP_SECONDS = 7;     // length of each scene (keep in sync with "Pick Clips" and "Plan Audio")
const FADE = 0.6;           // cross-dissolve length between scenes
const TRANSITION = 'fade';  // any ffmpeg xfade transition: fade, smoothup, smoothleft, fadeblack, circleopen...
const VW = 1080, VH = 1920, FPS = 30;
const AMBIENCE_VOLUME = 0.85; // generated natural sound of each scene
const MUSIC_VOLUME = 0.45;    // generated score underneath (Veo-style mix: sound first, music as a bed)
const LOOP_XFADE = 1.5;       // crossfade used to loop a short generated music cue smoothly
// ===============================================

const d = $('Pick Clips').first().json;
const plan = $('Plan Audio').first().json;           // job folder + music settings
const gen = $input.all().map(i => i.json);           // results of "Generate Sound (local AI)"
const clips = d.clips;
const N = clips.length;
const D = CLIP_SECONDS;
const TOTAL = +(N * D - (N - 1) * FADE).toFixed(2);
const job = plan.job;
const dir = plan.job_dir;
const genOk = gen.filter(g => g.path && !g.error).length;

const b64 = s => (typeof Buffer !== 'undefined')
  ? Buffer.from(s, 'utf8').toString('base64')
  : btoa(unescape(encodeURIComponent(s)));
const f2 = n => (+n).toFixed(2);
// Keep letters (all languages), numbers, punctuation, spaces. Drops emojis the font can't draw.
const clean = s => String(s || '').replace(/[^\p{L}\p{M}\p{N}\p{P}\p{Zs}]/gu, '').replace(/\s+/g, ' ').trim();
const wrap = (s, max, maxLines = 3) => {
  const lines = [];
  let cur = '';
  for (const w of clean(s).split(' ').filter(Boolean)) {
    if (cur && (cur + ' ' + w).length > max) { lines.push(cur); cur = w; }
    else cur = cur ? cur + ' ' + w : w;
  }
  if (cur) lines.push(cur);
  return lines.slice(0, maxLines);
};
const shq = s => String(s).replace(/'/g, '%27'); // URLs go inside single quotes

// Opacity envelope: fade in at a, fade out ending at e (per-clip time).
const alpha = (a, e, fin, fout) => {
  const inPart = fin > 0 ? `if(lt(t,${f2(a)}),0,if(lt(t,${f2(a + fin)}),(t-${f2(a)})/${f2(fin)},` : '';
  const close = fin > 0 ? '))' : '';
  return `'${inPart}if(lt(t,${f2(e - fout)}),1,if(lt(t,${f2(e)}),(${f2(e)}-t)/${f2(fout)},0))${close}'`;
};

const textFiles = [];
const drawtext = (text, size, y, alphaExpr) => {
  const name = `t${textFiles.length}.txt`;
  textFiles.push(`echo '${b64(text)}' | base64 -d > ${name}`);
  return `drawtext=fontfile=$FONT:textfile=${name}:expansion=none:fontsize=${size}:fontcolor=white` +
    `:shadowcolor=black@0.55:shadowx=0:shadowy=4:borderw=1:bordercolor=black@0.25` +
    `:x=(w-text_w)/2:y=${y}:alpha=${alphaExpr}`;
};

const clipCmds = clips.map((c, i) => {
  const isFirst = i === 0, isLast = i === N - 1;
  const end = isLast ? D - 0.35 : D - FADE;
  const texts = [];

  // Top text: hook on scene 1 (visible from frame 1 for sound-off viewers), overlay line on the others.
  const top = isFirst ? wrap(d.hook, 22, 4) : wrap(c.overlay, 24, 3);
  const size = isFirst ? 78 : 64;
  const lh = Math.round(size * 1.28);
  const topAlpha = isFirst ? alpha(0, end, 0, 0.4) : alpha(0.45, end, 0.5, 0.4);
  top.forEach((line, j) => texts.push(drawtext(line, size, 300 + j * lh, topAlpha)));

  // Location label above the platform UI safe zone.
  const label = clean(c.label || c.destination).toUpperCase().slice(0, 34);
  if (label) texts.push(drawtext(label, 40, 1360, alpha(0.8, end, 0.5, 0.4)));

  const vf = [
    `scale=${VW}:${VH}:force_original_aspect_ratio=increase:flags=lanczos`,
    `crop=${VW}:${VH}`,
    `fps=${FPS}`,
    'setsar=1',
    'eq=contrast=1.05:saturation=1.12',
    'unsharp=5:5:0.35:5:5:0',
    'vignette=angle=0.35',
    ...texts,
    'format=yuv420p'
  ].join(',');

  return `dl '${shq(c.url)}' src${i}.mp4\n` +
    `ffmpeg -hide_banner -loglevel error -y -ss ${f2(c.start || 0)} -i src${i}.mp4 -t ${D} -an -vf "${vf}" ` +
    `-r ${FPS} -c:v libx264 -preset veryfast -crf 16 -pix_fmt yuv420p c${i}.mp4 && rm -f src${i}.mp4`;
});

// Stitch: cross-dissolves between scenes + fade-out at the end.
const inputs = clips.map((_, i) => `-i c${i}.mp4`).join(' ');
let fc = clips.map((_, i) => `[${i}:v]settb=AVTB,setpts=PTS-STARTPTS[s${i}]`).join(';');
let prev = 's0';
for (let i = 1; i < N; i++) {
  const out = i === N - 1 ? 'xl' : `x${i}`;
  fc += `;[${prev}][s${i}]xfade=transition=${TRANSITION}:duration=${FADE}:offset=${f2(i * (D - FADE))}[${out}]`;
  prev = out;
}
if (N === 1) fc += ';[s0]null[xl]';
fc += `;[xl]fade=t=out:st=${f2(TOTAL - 0.5)}:d=0.5[vout]`;

// Audio graph: scene ambiences cross-faded exactly like the video, music bed underneath, -14 LUFS master.
const AF = 'aresample=48000,aformat=sample_fmts=fltp:channel_layouts=stereo';
const ambInputs = clips.map((_, i) => `-i amb${i}.wav`).join(' ');
clips.forEach((_, i) => { fc += `;[${N + i}:a]${AF},apad,atrim=0:${D},asetpts=PTS-STARTPTS[a${i}]`; });
let aprev = 'a0';
for (let i = 1; i < N; i++) {
  fc += `;[${aprev}][a${i}]acrossfade=d=${FADE}:c1=tri:c2=tri[ax${i}]`;
  aprev = `ax${i}`;
}
fc += `;[${aprev}]volume=${AMBIENCE_VOLUME}[amb];[${2 * N}:a]${AF},volume=${MUSIC_VOLUME}[mus]` +
  `;[amb][mus]amix=inputs=2:duration=first:normalize=0,loudnorm=I=-14:TP=-1.5:LRA=11,${AF}` +
  `,afade=t=in:st=0:d=0.15,afade=t=out:st=${f2(TOTAL - 1.5)}:d=1.5,atrim=0:${TOTAL}[aout]`;

// Smooth loop of the (short) generated music cue: k copies chained with crossfades, trimmed to the video length.
const L = Math.max(LOOP_XFADE + 1, Number(plan.music_seconds) || 11);
const k = Math.max(2, Math.ceil((TOTAL - LOOP_XFADE) / (L - LOOP_XFADE)) + 1);
let musicLoop = `[0:a]${AF},asplit=${k}${Array.from({ length: k }, (_, i) => `[m${i}]`).join('')}`;
let mprev = 'm0';
for (let i = 1; i < k; i++) { musicLoop += `;[${mprev}][m${i}]acrossfade=d=${LOOP_XFADE}[ml${i}]`; mprev = `ml${i}`; }
musicLoop += `;[${mprev}]atrim=0:${TOTAL},asetpts=PTS-STARTPTS[m]`;

const mood = ['calm', 'uplifting', 'epic', 'emotional'].includes(d.music_mood) ? d.music_mood : 'calm';
const AUDIO_EXT = `\\( -iname '*.mp3' -o -iname '*.m4a' -o -iname '*.wav' -o -iname '*.aac' -o -iname '*.ogg' -o -iname '*.flac' \\)`;

const script = `#!/bin/sh
set -e
DIR='${dir}'
mkdir -p "$DIR" && cd "$DIR"
FONT='${FONT}'
[ -f "$FONT" ] || FONT='${FONT_FALLBACK}'
${textFiles.join('\n')}
# download helper (uses the Node.js that ships with n8n, no curl/wget needed)
dl() { node -e 'const [u,f]=process.argv.slice(1);const fs=require("fs");const {Readable}=require("stream");const {pipeline}=require("stream/promises");fetch(u,{headers:{"User-Agent":"Mozilla/5.0"}}).then(r=>{if(!r.ok)throw new Error("HTTP "+r.status+" "+u);return pipeline(Readable.fromWeb(r.body),fs.createWriteStream(f))}).catch(e=>{console.error(e.message);process.exit(1)})' "$1" "$2"; }

# 1) Download, trim, crop to 9:16, grade and title each clip
${clipCmds.join('\n')}

# 2) Sound design
# 2a) Generated ambience per scene (missing/failed -> silence for that scene)
for i in ${clips.map((_, i) => i).join(' ')}; do
  [ -s "amb$i.wav" ] || ffmpeg -hide_banner -loglevel error -y -f lavfi -i anullsrc=r=48000:cl=stereo -t ${D} "amb$i.wav"
done
# 2b) Music bed: generated score (looped smoothly to full length), else a folder track, else silence
MUSIC=""
if [ -s music_gen.wav ]; then
  MUSIC=generated
  ffmpeg -hide_banner -loglevel error -y -i music_gen.wav -filter_complex "${musicLoop}" -map "[m]" -ar 48000 -ac 2 music.wav
else
  pick_music() { find "$1" -maxdepth "$2" -type f ${AUDIO_EXT} 2>/dev/null | awk 'BEGIN{srand()}{a[NR]=$0}END{if(NR)print a[int(rand()*NR)+1]}'; }
  MUSIC=$(pick_music '${MUSIC_DIR}/${mood}' 1)
  [ -n "$MUSIC" ] || MUSIC=$(pick_music '${MUSIC_DIR}' 2)
  if [ -n "$MUSIC" ]; then
    ffmpeg -hide_banner -loglevel error -y -stream_loop -1 -i "$MUSIC" -t ${TOTAL} -ar 48000 -ac 2 music.wav
  else
    ffmpeg -hide_banner -loglevel error -y -f lavfi -i anullsrc=r=48000:cl=stereo -t ${TOTAL} music.wav
  fi
fi

# 3) Stitch with cross-dissolves and export (H.264 High, 1080x1920, 30fps, AAC)
ffmpeg -hide_banner -loglevel error -y ${inputs} ${ambInputs} -i music.wav -filter_complex "${fc}" -map "[vout]" -map "[aout]" -c:v libx264 -preset slow -crf 18 -profile:v high -pix_fmt yuv420p -r ${FPS} -g ${FPS * 2} -c:a aac -b:a 192k -ar 48000 -movflags +faststart -t ${TOTAL} final.mp4
[ -s final.mp4 ]
echo "MUSIC=\${MUSIC:-none} SOUNDS_GENERATED=${genOk}/${gen.length}"
echo "$DIR/final.mp4"
`;

const slug = clean(d.title || 'short').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-|-$/g, '').slice(0, 60) || 'short';
return [{ json: {
  ...d,
  job: job,
  job_dir: dir,
  sound: gen.map(g => g.error ? `failed: ${String(g.error.message || g.error).slice(0, 120)}` : `${g.path} (${g.took}s)`),
  output_path: `${dir}/final.mp4`,
  file_name: `${slug}-${job}.mp4`,
  duration: TOTAL,
  command: `mkdir -p '${dir}' && echo '${b64(script)}' | base64 -d > '${dir}/render.sh' && sh '${dir}/render.sh'`
}}];

const id = $('Upload to Drive').first().json.id;
if (!id) throw new Error('Google Drive upload returned no file id');
const meta = $('Build Render Script').first().json;
return [{ json: {
  row_number: meta.row_number,
  title: meta.title,
  caption: meta.caption,
  credits: meta.credits,
  file_id: id,
  url: `https://drive.google.com/uc?export=download&id=${id}`,
  view_url: `https://drive.google.com/file/d/${id}/view`
}}];
